    bronze_glasskilndoorchain = { name = "Bronast veriga za vrata peči", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast veriga za vrata peči za steklarje." },
    silver_glasskilndoorchain = { name = "Srebrn veriga za vrata peči", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn veriga za vrata peči za steklarje." },
    gilded_glasskilndoorchain = { name = "Pozlačen veriga za vrata peči", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen veriga za vrata peči za steklarje." },
    jewel_set_glasskilndoorchain = { name = "Draguljast veriga za vrata peči", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast veriga za vrata peči za steklarje." },
    royal_sovereign_glasskilndoorchain = { name = "Kraljevski suveren veriga za vrata peči", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren veriga za vrata peči z biseri za krono." },
}
