    master_glasskilndoorchain_atelier = { name = "Mojstrski glasskilndoorchain atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_glasskilndoorchain_palace = { name = "Suverena glasskilndoorchain palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
GlassKilnDoorChainMaker.ironStock=16; GlassKilnDoorChainMaker.bronzeStock=12; GlassKilnDoorChainMaker.woodStock=12; GlassKilnDoorChainMaker.leatherStock=8; GlassKilnDoorChainMaker.silverStock=8; GlassKilnDoorChainMaker.goldStock=6; GlassKilnDoorChainMaker.jewelStock=4; GlassKilnDoorChainMaker.pearlStock=4
GlassKilnDoorChainMaker.productStock = {}; GlassKilnDoorChainMaker.buildings = {}; GlassKilnDoorChainMaker.maker = nil; GlassKilnDoorChainMaker.activeMaking = {}; GlassKilnDoorChainMaker.totalProducts = 0; GlassKilnDoorChainMaker.dayTimer = 0
function GlassKilnDoorChainMaker.init() GlassKilnDoorChainMaker.ironStock=16; GlassKilnDoorChainMaker.bronzeStock=12; GlassKilnDoorChainMaker.woodStock=12; GlassKilnDoorChainMaker.leatherStock=8; GlassKilnDoorChainMaker.silverStock=8; GlassKilnDoorChainMaker.goldStock=6; GlassKilnDoorChainMaker.jewelStock=4; GlassKilnDoorChainMaker.pearlStock=4; GlassKilnDoorChainMaker.productStock={}; GlassKilnDoorChainMaker.buildings={}; GlassKilnDoorChainMaker.maker=nil; GlassKilnDoorChainMaker.activeMaking={}; GlassKilnDoorChainMaker.totalProducts=0; GlassKilnDoorChainMaker.dayTimer=0; print("[GlassKilnDoorChainMaker] Royal Glass Kiln Door Chain Maker System initialized (6 products, 4 buildings)") end
function GlassKilnDoorChainMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GlassKilnDoorChainMaker.maker={name=n or ("Verižnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Verižnik najet: %s (spretnost: %d)",GlassKilnDoorChainMaker.maker.name,s),"success") end; return true end
function GlassKilnDoorChainMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GlassKilnDoorChainMaker.build(id) local ok,e=GlassKilnDoorChainMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GlassKilnDoorChainMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GlassKilnDoorChainMaker.getQualityBonus() local b=0; for _,bd in ipairs(GlassKilnDoorChainMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GlassKilnDoorChainMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GlassKilnDoorChainMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GlassKilnDoorChainMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GlassKilnDoorChainMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GlassKilnDoorChainMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GlassKilnDoorChainMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GlassKilnDoorChainMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GlassKilnDoorChainMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GlassKilnDoorChainMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GlassKilnDoorChainMaker.buildings==0 then return false,"Potrebna verižna delavnica" end; if not GlassKilnDoorChainMaker.maker then return false,"Potreben veriznik" end; return true end
function GlassKilnDoorChainMaker.make(pt,qty) qty=qty or 1; local ok,e=GlassKilnDoorChainMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GlassKilnDoorChainMaker.ironStock=GlassKilnDoorChainMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GlassKilnDoorChainMaker.bronzeStock=GlassKilnDoorChainMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GlassKilnDoorChainMaker.woodStock=GlassKilnDoorChainMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GlassKilnDoorChainMaker.leatherStock=GlassKilnDoorChainMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GlassKilnDoorChainMaker.silverStock=GlassKilnDoorChainMaker.silverStock-d.silverCost*qty end; if d.goldCost then GlassKilnDoorChainMaker.goldStock=GlassKilnDoorChainMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GlassKilnDoorChainMaker.jewelStock=GlassKilnDoorChainMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GlassKilnDoorChainMaker.pearlStock=GlassKilnDoorChainMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GlassKilnDoorChainMaker.maker then t=math.max(1,t-math.floor(GlassKilnDoorChainMaker.maker.skill/13)) end; table.insert(GlassKilnDoorChainMaker.activeMaking,{id="glasskilndoorchain_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GlassKilnDoorChainMaker.completeMaking(m) local q=1.0+(GlassKilnDoorChainMaker.getQualityBonus()/100); if GlassKilnDoorChainMaker.maker then q=q+(GlassKilnDoorChainMaker.maker.skill/140) end; q=math.min(2.5,q); GlassKilnDoorChainMaker.productStock[m.productType]=(GlassKilnDoorChainMaker.productStock[m.productType] or 0)+m.quantity; GlassKilnDoorChainMaker.totalProducts=GlassKilnDoorChainMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassKilnDoorChainMaker.maker then GlassKilnDoorChainMaker.maker.itemsMade=GlassKilnDoorChainMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassKilnDoorChainMaker.maker.skill=math.min(100,GlassKilnDoorChainMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Veriga izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glasskilndoorchain.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GlassKilnDoorChainMaker.update(dt) if not _G.state then return end; GlassKilnDoorChainMaker.dayTimer=GlassKilnDoorChainMaker.dayTimer+dt; if GlassKilnDoorChainMaker.dayTimer>=30 then GlassKilnDoorChainMaker.dayTimer=0; for i=#GlassKilnDoorChainMaker.activeMaking,1,-1 do local m=GlassKilnDoorChainMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassKilnDoorChainMaker.completeMaking(m); table.remove(GlassKilnDoorChainMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassKilnDoorChainMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassKilnDoorChainMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GlassKilnDoorChainMaker.getStats() return {ironStock=GlassKilnDoorChainMaker.ironStock,bronzeStock=GlassKilnDoorChainMaker.bronzeStock,woodStock=GlassKilnDoorChainMaker.woodStock,leatherStock=GlassKilnDoorChainMaker.leatherStock,silverStock=GlassKilnDoorChainMaker.silverStock,goldStock=GlassKilnDoorChainMaker.goldStock,jewelStock=GlassKilnDoorChainMaker.jewelStock,pearlStock=GlassKilnDoorChainMaker.pearlStock,productStock=GlassKilnDoorChainMaker.productStock,numBuildings=#GlassKilnDoorChainMaker.buildings,hasMaker=GlassKilnDoorChainMaker.maker~=nil,makerName=GlassKilnDoorChainMaker.maker and GlassKilnDoorChainMaker.maker.name or "—",makerSkill=GlassKilnDoorChainMaker.maker and GlassKilnDoorChainMaker.maker.skill or 0,activeMaking=#GlassKilnDoorChainMaker.activeMaking,totalProducts=GlassKilnDoorChainMaker.totalProducts} end
return GlassKilnDoorChainMaker
